package com.yuegang.zhihui.order.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.order.api.*;import com.yuegang.zhihui.product.api.*;import java.math.*;import java.util.*;import org.springframework.core.ParameterizedTypeReference;import org.springframework.web.client.RestClient;public final class CheckoutService{private final RestClient products;public CheckoutService(String base){products=RestClient.builder().baseUrl(base).build();}public OrderPreviewView preview(CreateOrderRequest c){var items=new ArrayList<OrderItemCommand>();BigDecimal total=BigDecimal.ZERO;for(var requested:c.items()){ApiResponse<ProductView>response=products.get().uri("/api/v1/products/"+requested.skuId()).retrieve().body(new ParameterizedTypeReference<>(){});if(response==null||response.data()==null||response.data().status()!=ProductStatus.PUBLISHED)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);var p=response.data();var item=new OrderItemCommand(p.skuId(),p.skuCode(),p.name(),p.price(),requested.quantity());items.add(item);total=total.add(p.price().multiply(BigDecimal.valueOf(requested.quantity())));}return new OrderPreviewView(items,total,"CNY",c.address(),List.of());}public CreateOrderRequest trusted(CreateOrderRequest c){var p=preview(c);return new CreateOrderRequest(c.requestId(),p.items(),p.address(),c.remark());}}
